// Kiss of Death / Поцелуй Смерти (Дар Слаанеш, wdbc-1rno) — встречный
// психический тест W+Cor.b×5 vs W+Cor.b×5. Победа — d10 непоглощаемого
// Rending урона за каждый Успех (margin), прямо в Раны/Критические, минуя
// броню (woundLossUpdates — та же арифметика, что у боевого урона). Смерть
// цели даёт бонусы носителю и метит жертву флагом для удвоенной цены
// Спасения (sheets/tabs/death.mjs::KISS_OF_DEATH_FLAG).
const targetDoc = game.user.targets?.first?.() ?? [...(game.user.targets ?? [])][0];
const targetActor = targetDoc?.actor ?? null;
if (!targetActor) {
  ui.notifications?.warn("Поцелуй Смерти: выберите одну цель.");
} else {
  const myCorB = Number(actor.system?.corruptionBonus) || 0;
  const myWp = Number(actor.system?.characteristics?.wp?.total) || 0;
  const myThreshold = myWp + myCorB * 5;
  const theirCorB = Number(targetActor.system?.corruptionBonus) || 0;
  const theirWp = Number(targetActor.system?.characteristics?.wp?.total) || 0;
  const theirThreshold = theirWp + theirCorB * 5;

  const myRoll = await new Roll("1d100").evaluate();
  const theirRoll = await new Roll("1d100").evaluate();
  const mine = { ...testOutcome(myRoll.total, myThreshold), threshold: myThreshold };
  const theirs = { ...testOutcome(theirRoll.total, theirThreshold), threshold: theirThreshold };
  const { winner, margin } = resolveOpposed(mine, theirs);

  const lines = [
    `${actor.name}: <b>${myRoll.total}</b> vs ${myThreshold} (W ${myWp} + Cor.b ${myCorB}×5) ${mine.success ? "(успех)" : "(провал)"}`,
    `${targetActor.name}: <b>${theirRoll.total}</b> vs ${theirThreshold} (W ${theirWp} + Cor.b ${theirCorB}×5) ${theirs.success ? "(успех)" : "(провал)"}`
  ];
  const rolls = [myRoll, theirRoll];
  let deathBtn = "";

  if (winner !== "mine") {
    lines.push(`<b>Жертва выстояла</b> — Поцелуй не причинил вреда.`);
  } else {
    const dmgRoll = await new Roll(`${margin}d10`).evaluate();
    rolls.push(dmgRoll);
    const dmg = dmgRoll.total;
    lines.push(`Победа с margin <b>${margin}</b> — урон <b>${dmg}</b> непоглощаемого R Dmg (${margin}d10).`);

    const woundsUpd = woundLossUpdates(targetActor.system, dmg);
    await targetActor.update(woundsUpd);

    const deathThreshold = woundDeathThreshold(targetActor.system.wounds?.max);
    const dead = (woundsUpd["system.wounds.critical"] || 0) >= deathThreshold;

    if (dead) {
      const infamyRoll = await new Roll("1d5").evaluate();
      rolls.push(infamyRoll);
      await changeActorInfamy(actor, infamyRoll.total);
      const myWpBonus = Number(actor.system?.characteristics?.wp?.bonus) || 0;
      const healRoll = await new Roll("1d10").evaluate();
      rolls.push(healRoll);
      const healUpd = computeWoundHealing(actor.system, healRoll.total + myWpBonus);
      await actor.update({ "system.fatigue.value": 0, ...healUpd });
      await targetActor.setFlag("warhammer-dbc", "killedByKissOfDeath", true);

      lines.push(`<b>Смертельно</b> — ${actor.name} восстанавливает +${infamyRoll.total} Бесчестия, снимает всю Усталость, лечит ${healRoll.total}+${myWpBonus} Ран.`);
      deathBtn = `<div class="wh-crit-pills"><button type="button" class="wh-crit-death-btn" data-actor-uuid="${targetActor.uuid}" data-weapon-uuid="">💀 Констатировать смерть</button></div>`;
    }
  }

  await ChatMessage.create(ChatMessage.applyRollMode({
    speaker,
    content: `<div class="wh-roll-result">
      <div class="roll-header">Поцелуй Смерти — ${actor.name} → ${targetActor.name}</div>
      <div class="roll-threshold">${lines.join("<br/>")}</div>
      ${deathBtn}
    </div>`,
    rolls
  }, game.settings.get("core", "rollMode")));
}
